'use strict';
(function(){
 let panel=null,poll=0,applied=false;
 async function close(){clearInterval(poll);panel?.remove();panel=null;await invoke('chromeLoginCancel').catch(()=>{})}
 async function open(){await close();const node=document.createElement('div');node.className='chrome-login-panel';node.innerHTML=`<section class="chrome-login-card" role="dialog" aria-modal="true" aria-label="从 Chrome 同步 Bangumi 登录"><button class="sheet-close" data-chrome-close aria-label="关闭">${svg('close')}</button><p class="detail-kicker">CONTINUE WITH CHROME</p><h2>沿用已登录的 Chrome</h2><p>使用浏览器扩展同步 Bangumi 登录，省去在小窗口重新验证。</p><ol><li>在 Chrome 打开 <b>chrome://extensions</b>，开启开发者模式，选择“加载已解压的扩展程序”，选取下方打开的文件夹。首次安装即可。</li><li>在 Chrome 登录对应的 Bangumi 网站，再打开“映迹 · Bangumi 登录同步”扩展。</li><li>复制连接码，在扩展里粘贴，点击“同步登录到映迹”。</li></ol><div class="button-group"><button class="button secondary" data-chrome-folder>${svg('folder')}打开扩展文件夹</button><button class="button secondary" data-chrome-copy>${svg('copy')}复制连接码</button></div><button class="ghost-link" data-chrome-retry>重新生成连接码</button><label for="chromePairCode">连接码 · 10 分钟内有效</label><input id="chromePairCode" class="form-input" readonly spellcheck="false"><p id="chromeSyncStatus" role="status">正在生成连接码…</p><small>仅同步所选 Bangumi 网站；数据只发往本机映迹。Cookie 不会显示在这里。</small></section>`;document.body.append(node);panel=node;applied=false;
  node.querySelector('[data-chrome-close]').onclick=close;node.querySelector('[data-chrome-retry]').onclick=open;node.addEventListener('click',e=>{if(e.target===node)close()});node.querySelector('[data-chrome-folder]').onclick=()=>invoke('chromeLoginFolder').catch(e=>toast(e.message));node.querySelector('[data-chrome-copy]').onclick=()=>invoke('chromeLoginCopy').then(()=>toast('连接码已复制')).catch(e=>toast(e.message));
  try{const pair=await invoke('chromeLoginStart');if(panel!==node)return;node.querySelector('#chromePairCode').value=pair.code;node.querySelector('#chromeSyncStatus').textContent=pair.message;node.querySelector('[data-chrome-copy]').focus();poll=setInterval(async()=>{try{const info=await invoke('chromeLoginStatus');if(panel!==node)return;node.querySelector('#chromeSyncStatus').textContent=info.message;if(['connected','unverified','expired','error'].includes(info.stage)){clearInterval(poll);if(!applied&&['connected','unverified'].includes(info.stage)){applied=true;if(state.tab==='catalog')await loadCatalog(true);if(info.stage==='connected')toast('已复用 Chrome 的 Bangumi 登录')}}}catch{}},800)}catch(e){node.querySelector('#chromeSyncStatus').textContent=e.message}
 }
 function decorate(){if(catalogClient.provider!=='bangumi')return;const note=$('.catalog-note');if(note&&!note.querySelector('[data-chrome-login]'))note.insertAdjacentHTML('beforeend',`<button class="source-web-button" data-chrome-login>${svg('external')}Chrome 登录</button>`);const error=$('#catalogResults .catalog-empty');if(error&&!error.querySelector('[data-chrome-login]'))error.insertAdjacentHTML('beforeend','<button class="button secondary" data-chrome-login>从 Chrome 同步登录</button>')}
 const base=renderCatalogResults;renderCatalogResults=function(){const result=base();decorate();return result};
 const settingsBase=renderSettings;renderSettings=function(){settingsBase();$('#main').insertAdjacentHTML('beforeend',`<section class="chrome-login-settings"><h3>Bangumi 浏览器登录</h3><p>在 Chrome 已登录时，可以通过扩展同步到映迹。</p><button class="button secondary" data-chrome-login>从 Chrome 同步登录</button></section>`)};
 document.addEventListener('click',e=>{if(e.target.closest('[data-chrome-login]')){e.preventDefault();e.stopImmediatePropagation();open()}},true);document.addEventListener('keydown',e=>{if(panel&&e.key==='Escape'){e.preventDefault();close()}},true);decorate();window.YingjiChromeLogin={open,close,version:'0.4.14'};
})();
